    }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 09. 21
 * @description 업무처리번호로 상세를 조회해 dma_item 과 변경 전·후 결산기 목록(dlt_fscBf·dlt_fscAf)에 담고, 결과에 맞춰 버튼 상태를 정한다.
 *
 * 응답 한 건에 DataMap 과 DataList 2개를 함께 받으므로 target 을 쉼표로 나열한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 요청 파라미터, 응답 키(bfList·afList)
 * @param
 * @returns
 * @hidden N
*/
scwin.selectOne = async function () {
    dma_item.setEmptyValue();
    dlt_fscBf.removeAll();
    dlt_fscAf.removeAll();

    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/stock/fsc-change/select-one",
        target : "dma_item=body,dlt_fscBf=body.bfList,dlt_fscAf=body.afList",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : scwin.bzProcsNo
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    // 여기서 잡지 않으므로 오류가 나면 아래 처리는 실행되지 않는다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return;

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.saveFscChange
 * @author Inswave
 * @date 2026. 09. 21
 * @description 결산기 변경 정보를 저장(I)·수정(U)·삭제(D)한다. 저장·수정 후에는 부모 목록을 재조회하고 상세를 다시 조회하며, 삭제 후에는 팝업을 닫는다.
 *
 * 요청 전문은 화면 DataMap(dma_item)을 dma_in 에 복사한 뒤 화면에 없는 값을 덧붙이고,
 * 변경 전·후 결산기 목록(DataList 2개)을 bfList·afList 로 함께 싣는다.
 * 세 처리는 전문이 같고 action 만 다르므로 한 함수에서 분기한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 화면에 없는 고정값, 목록 키 이름
 * @param {String} trJob 처리구분 I: 저장, U: 수정, D: 삭제
 * @returns
 * @hidden N
*/
scwin.saveFscChange = async function (trJob) {
    dma_in.setEmptyValue();
    dma_in.setJSON(dma_item.getJSON());

    // 조회 결과에 없으면 부모에서 받아 둔 값을 쓴다.
    dma_in.set("bzProcsNo", $c.util.isEmpty(dma_item.get("bzProcsNo")) ? scwin.bzProcsNo : dma_item.get("bzProcsNo"));   // 업무처리번호 (신규는 save 가 채번해 dma_item 에 넣어 둔다)
    dma_in.set("isurCd", $c.util.isEmpty(dma_item.get("isurCd")) ? scwin.isurCd : dma_item.get("isurCd"));               // 발행기관코드
    dma_in.set("mktTpCd", $c.util.isEmpty(dma_item.get("mktTpCd")) ? scwin.mktTpCd : dma_item.get("mktTpCd"));           // 시장구분코드
    dma_in.set("listBzTpCd", scwin.LIST_BZ_TP_CD);                                                                         // 상장업무유형 231: 결산기변경

    const svcId = { I : "insert", U : "update", D : "delete" }[trJob];

    const sbmOptions = {
        id : "sbm_saveFscChange",
        method : "post",
        action : "/api/listing/lstproc/stock/fsc-change/" + svcId,
        mediatype : "application/json",
        isProcessMsg : false
    };

    // DataMap 과 DataList 2개를 한 전문으로 보낸다. ref 대신 요청 데이터를 직접 만든다.
    const requestData = {
        ...dma_in.getJSON(),
        bfList : dlt_fscBf.getAllJSON(),    // 변경전 결산기 목록
        afList : dlt_fscAf.getAllJSON()     // 변경후 결산기 목록
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return;

    scwin.refreshParent();

    // "com_complete_0096": "$[0] 되었습니다."
    const jobNm = { I : "저장", U : "수정", D : "삭제" }[trJob];
    await $c.win.alert($c.data.getMessage("com_complete_0096", jobNm));

    // 삭제한 건은 더 볼 것이 없다.
    if (trJob === "D") {
        $c.win.closePopup();
        return;
    }

    // 저장이 성공한 뒤에야 수정 모드가 된다.
    scwin.bzProcsNo = dma_in.get("bzProcsNo");

    await scwin.selectOne();
};


