/**
 * @method
 * @name scwin.setFormState
 * @author Inswave
 * @date 2026. 09. 21
 * @description 신규·수정·시장조치시행일 경과에 따라 버튼 상태를 정한다.
 *
 * 조회가 끝날 때마다 부르므로 상태 판정을 한 곳에 모아 둔다.
 *  - 신규(업무처리번호 없음)              : [저장]만 활성
 *  - 수정(시장조치시행일이 현재일 이후)   : [수정]·[삭제]·[기안]·[안내문작성] 활성
 *  - 시장조치시행일 경과(이미 반영)       : [기안]만 활성 (상태 error — 입력은 잠그지 않고 열람만 허용)
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 상태 판정 기준 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.setFormState = function () {
    const isNew = $c.util.isEmpty(scwin.bzProcsNo);

    if (isNew) {
        $c.util.setButtonState("grp_btnBox", "insert", scwin.BTN_MAP);
        return;
    }

    // 시장조치시행일이 지나지 않은 건만 수정·삭제할 수 있다. 지난 건은 기안만 남긴다.
    const enfrcDd = ica_MKTACT_ENFRC_DD.getValue();
    const status = ($c.util.isEmpty(enfrcDd) || enfrcDd > scwin.curDate) ? "update" : "error";

    $c.util.setButtonState("grp_btnBox", status, scwin.BTN_MAP);
};

