/**
 * @method
 * @name scwin.removeFscRow
 * @author Inswave
 * @date 2026. 09. 21
 * @description 그리드에서 선택한 행을 결산기 목록(DataList)에서 지운다. 선택한 행이 없으면 안내한다.
 * @param {Object} gridView 대상 gridView (grd_fscBf | grd_fscAf)
 * @param {Object} dataList 대상 DataList (dlt_fscBf | dlt_fscAf)
 * @returns
 * @hidden N
*/
scwin.removeFscRow = async function (gridView, dataList) {
    const row = gridView.getFocusedRowIndex();

    if (row < 0) {
        await $c.win.alert("삭제할 행을 선택하세요.");
        return;
    }

    dataList.removeRow(row);
};

/**
 * @method
 * @name scwin.validateFscGrid
 * @author Inswave
 * @date 2026. 09. 21
 * @description 결산기 목록(DataList)의 행마다 월·일을 검증한다. 문제가 있으면 안내하고 해당 셀에 포커스를 준 뒤 false 를 돌려준다.
 *
 * 업무공통 $c.lc.checkAcntclsMMDD 는 단일 입력 컴포넌트(MMDD 4자리)용이라 그리드 행에는 쓸 수 없어 같은 기준을 행 단위로 옮겼다.
 *  - 월·일 모두 2자리 숫자 필수 (1월 → 01)
 *  - 월 01~12, 일 01~31, 그리고 그 달에 실재하는 날짜(2월은 29일까지 허용)
 * @param {Object} gridView 대상 gridView (포커스 이동용)
 * @param {Object} dataList 대상 DataList
 * @param {String} name 안내문에 쓸 표 이름 (변경전 | 변경후)
 * @param {Boolean} required 행이 하나도 없으면 오류로 볼지 여부
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validateFscGrid = async function (gridView, dataList, name, required) {
    const rowCount = dataList.getRowCount();

    if (rowCount === 0) {
        if (!required) return true;
        await $c.win.alert("[" + name + " 결산기]를 한 건 이상 입력하세요.");
        gridView.focus();
        return false;
    }

    const LAST_DAY = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

    for (let i = 0; i < rowCount; i++) {
        const mm = String(dataList.getCellData(i, "acntclsMm") ?? "");
        const dd = String(dataList.getCellData(i, "acntclsDd") ?? "");
        const rowNo = i + 1;

        if (!/^\d{2}$/.test(mm)) {
            await $c.win.alert("[" + name + " 결산기] " + rowNo + "행의 [월]을 올바르게 입력하세요. 1월 -> 01");
            gridView.setFocusedCell(i, "acntclsMm");
            return false;
        }

        if (!/^\d{2}$/.test(dd)) {
            await $c.win.alert("[" + name + " 결산기] " + rowNo + "행의 [일]을 올바르게 입력하세요. 1일 -> 01");
            gridView.setFocusedCell(i, "acntclsDd");
            return false;
        }

        const month = Number(mm);
        const day = Number(dd);

        if (month < 1 || month > 12) {
            await $c.win.alert("[" + name + " 결산기] " + rowNo + "행의 [월]이 12월을 초과하였습니다. 다시 입력하세요.");
            gridView.setFocusedCell(i, "acntclsMm");
            return false;
        }

        if (day < 1 || day > LAST_DAY[month - 1]) {
            await $c.win.alert("[" + name + " 결산기] " + rowNo + "행의 [일]이 " + month + "월에 없는 날짜입니다. 다시 입력하세요.");
            gridView.setFocusedCell(i, "acntclsDd");
            return false;
        }
    }

    return true;
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 09. 21
 * @description 저장·수정 전 입력값을 검증한다.
 *
 * 필수·날짜 형식·길이는 gcc 공통 검증 $c.validate.validateDataCollect 로 본다
 * (실패 시 표준 alert 과 대상 포커스를 공통이 처리, async 라 await 필요).
 * 그리드 행(변경 전·후 결산기)은 DataMap 항목이 아니라 공통 검증 대상이 아니므로 validateFscGrid 로 따로 본다.
 * 사업연도 시작일·종료일의 선후 비교는 업무 조건이라 공통 검증 뒤에 별도로 본다.
 *
 * 기타의 byte 한도는 공통 검증 기준(UTF-8, 한글 3byte)으로 잰다. DB 컬럼 기준에 맞춰 maxLengthB 값을 조정한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - options.fields 검증 항목 (키 = 컴포넌트 ID)
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validate = async function () {
    const options = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            ibx_ISUR_CD : { required : true, name : "회사코드" },
            ica_CHG_DD : { required : true, format : "date", name : "변경일" },
            ica_MKTACT_ENFRC_DD : { required : true, format : "date", name : "시장조치시행일" },
            cmb_CHG_RSN_CD : { required : true, name : "변경사유" },
            txa_ETC_CONTN : { maxLengthB : 2000, name : "기타" },
            ica_FST_BZYY_STRT_DD : { format : "date", name : "변경 후 최초 사업연도 시작일" },
            ica_FST_BZYY_END_DD : { format : "date", name : "변경 후 최초 사업연도 종료일" }
        }
    };

    if (!await $c.validate.validateDataCollect(panel_item, options)) return false;

    // 변경전은 있으면 검사, 변경후는 한 건 이상 필수.
    if (!await scwin.validateFscGrid(grd_fscBf, dlt_fscBf, "변경전", false)) return false;
    if (!await scwin.validateFscGrid(grd_fscAf, dlt_fscAf, "변경후", true)) return false;

    // 사업연도 시작일은 종료일보다 앞서야 한다. 둘 다 입력한 경우에만 본다.
    const strtDd = ica_FST_BZYY_STRT_DD.getValue();
    const endDd = ica_FST_BZYY_END_DD.getValue();

    if (!$c.util.isEmpty(strtDd) && !$c.util.isEmpty(endDd) && strtDd >= endDd) {
        await $c.win.alert("[변경 후 최초 사업연도 시작일]은 [종료일]보다 작아야 합니다. 다시 입력해주세요");
        ica_FST_BZYY_STRT_DD.focus();
        return false;
    }

    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 21
 * @description 신규 저장. 검증과 확인을 거친 뒤 업무처리번호를 채번해 저장한다.
 *
 * 순서가 중요하다. 먼저 입력값을 검증하고, 사용자 확인을 받은 다음, 마지막에 채번한다.
 * 채번을 먼저 하면 취소한 건에도 번호가 소비된다.
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "저장하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    // 신규 업무처리번호 채번 (14자리). 저장이 성공하기 전에는 화면 상태값(scwin.bzProcsNo)에 넣지 않는다.
    // 미리 넣으면 저장 실패 후에도 수정 모드로 판정돼 [저장]이 잠긴다.
    const newBzProcsNo = await $c.stf.getNewBzProcNo();

    if ($c.str.getByteLength(String(newBzProcsNo)) !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        return;
    }

    dma_item.set("bzProcsNo", newBzProcsNo);

    await scwin.saveFscChange(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 09. 21
 * @description 수정. 검증과 확인을 거친 뒤 수정한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "수정하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveFscChange(scwin.trJob);
};

/**
 * @method
 * @name scwin.deleteOne
 * @author Inswave
 * @date 2026. 09. 21
 * @description 삭제. 확인을 받은 뒤 시장안내공시가 이미 승인된 건인지 확인하고 삭제한다.
 *
 * 승인된 공시가 있으면 업무공통이 안내하고 false 를 돌려주므로 여기서는 멈추기만 한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.deleteOne = async function () {
    scwin.trJob = "D";

    // "삭제하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    // 시장안내공시가 승인된 건은 삭제할 수 없다 (통신이 필요해 공통 검증으로 옮기지 않는다).
    if (!await $c.lc.checkDeleteDiscls(dma_procs, scwin.bzProcsNo)) return;

    await scwin.saveFscChange(scwin.trJob);
};

